package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaDoiDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_q_lut_najjini_ahli" to DuaText("लूत (ए. ऐस्स.) दी दुआ-मेरे परोआर गी बचाओ", "ऐ मेरे रब, मिगी ते मेरे परोआर गी उंʼदे कम्में दे नतीजे शा बचाओ।", "अपने परोआर गी बुराई दे माहौल शा बचाउणा।", "परोआर गी बुराई शा बचाओ।"),
        "dua_q_sulaiman_awzini" to DuaText("सुलेमान (ए. ऐस्स.) दा दुआ कृतज्ञता आस्तै", "ऐ मेरे रब, तुंʼदे ते मेरे माता-पिता पर होई दी कृपा आस्तै मैं तुंʼदी ते मां-बाप दी शुकरगुज़ार होई सकनां ते तुसें गी खुश करने आह्ले नेक कम्म करां ते अपनी दया कन्नै मिगी अपने नेक सेवकें च शामल करी सकां।", "आशीर्वाद आस्तै शुक्रगुजार होने दी क्षमता आस्तै।", "सुलेमान (ए. ऐस्स.) दा आभार प्रकट करना।"),
        "dua_q_musa_zalamtu" to DuaText("मूसा (ए. ऐस्स.) दी दुआ-में अपने आप कन्नै गलत कीता ऐ", "हे मेरे प्रभु, में अपने कन्नै अन्याय कीता ऐ, इस करियै मिगी माफ करी देओ।", "गलती दे परैंत्त फौरन पश्चाताप करना।", "अल्लाह ने मूसा (अ. स.) गी माफ करी ओड़ेआ।"),
        "dua_q_musa_najjini" to DuaText("मूसा (ए. ऐस्स.) दी दुआ-मिगी जुल्म करने आह्ले लोकें शा बचाओ", "ऐ मेरे रब, मिगी बदमाशी करने आह्ले लोकें शा बचाओ।", "जिसलै अत्याचारीएं शा डरदे ओ।", "मूसा (ए. ऐस्स.) दा दुआ जिसलै मिस्र थमां निकलदा ऐ।"),
        "dua_q_lut_unsurni" to DuaText("लूत (ए. ऐस्स.) दी दुआ-भ्रष्टें दे खलाफ मदद", "मेरे प्रभु, भ्रष्ट लोकें दे खलाफ मेरी मदद करो।", "भ्रष्टाचार फैलाने आह्ले लोकें दे खलाफ मदद आस्तै।", "सच्चै पर द्रिढ़ रेह् लोकें दी दुआ।"),
        "dua_q_hab_li_salihin" to DuaText("इक धर्मी ञ्याणे आस्तै इब्राहिम (ए. ऐस्स.) दा दुआ", "हे मेरे रब, सच्चें च थमां मिगी इक ञ्याणा देओ।", "धर्मी ञ्याणें दी मंग करना।", "एह्दे राहें दुआ इस्माइल (ए. ऐस्स.) मंजूर कीती गेई ही।"),
        "dua_q_wasita_kulla_shay" to DuaText("सिंहासन धारण करने आह्ले स्वर्गदूतां दा दुआ", "ऐ हमारे रब, तुस हर चीज गी दया ते ज्ञान कन्नै घेरे दी ऐ, इस करियै उʼनें गी माफ करी देओ जेह्ड़े पश्चाताप करदे न ते तुंʼदे रस्ते पर चलदे न, ते उʼनें गी नरक दी सʼजा शा बचाउंदे न।", "सिंहासन धारण करने आह्ले स्वर्गदूत विश्वासीएं आस्तै एह् दुआ करदे न।", "दूएं दे दुआ च शामल होने दे इरादे कन्नै पाठ कीता गेआ।"),
        "dua_q_ikhwanina" to DuaText("साडे भ्राऽएं आस्तै जेह्ड़े हमसे पैह्लें हे", "ऐ हमारे रब, सानू ते असां दे भ्राऽ, जेह्ड़े ईमान च हमसे पैह्लें आए हे, गी माफ करी देओ ते ईमान लाने आह्ले लोकें दे प्रति साडे मनें च कोई नाराज़गी नेईं पैदा करो। ऐ हमारे रब, तू बड़ा दयावान ते दयावान ऐ।", "उंʼदे शा पैह्लें आए दे विश्वासी लोकें आस्तै इक दुआ ते इक साफ-सुथरा दिल।", "कुलीन साथी (आर. ए.) ते पैह्लें दे विश्वासियें आस्तै इक दुआ।"),
        "dua_q_alayka_tawakkalna" to DuaText("हम तुंʼदे पर भरोसा करदे न (इब्राहिम ए. ऐस्स.)", "ऐ ऐ ऐ हमारे रब, असीं तेरे पर भरोसा करदे आं, हम तेरी बक्खी रुख करदे न ते तेरी बक्खी बापसी ऐ। ऐ ऐ हमारे रब, असां गी काफ़िरें आस्तै अज़माइश नेईं बनाओ ते सानू माफ़ करी देओ। ऐ ऐ हमारे रब, तू बड़ा बलवान, तत्वदर्शी ऐ।", "इब्राहिम (ए. ऐस्स.) ते उंʼदे साथीएं दी दुआ।", "अल्लाह पर भरोसा करने ते उंʼदी बक्खी रुख करने दा इक दुआ।"),
        "dua_q_atmim_nurana" to DuaText("हमारी रोशनी गी पूरी करो", "ऐ हमारे रब, साडे आस्तै हमारा चानण पूरी चाल्ली कन्नै त्यार करो ते सानू माफ करी देओ। तुस हर चीज पर काबले-जिकर ओ।", "क़ियामत दे दिन विश्वासीएं दी दुआ।", "सीराट पर लाइट मंगना।"),
        "dua_q_asiya_baytan" to DuaText("एशिया दा दुआ-जन्नत च इक घर", "ऐ मेरे रब, मेरे कोल अपने कोल इक घर बनाओ, फ़िरौन ते ओह्दे कम्में शा मिगी बचाओ ते मुझे बदमाशी करने आह्ले लोकें शा बचाओ।", "आसिया दी दुआ, फ़िरौन दी लाड़ी।", "अल्लाह ने उʼनें गी विश्वासी लोकें आस्तै इक मिसाल बनाई।"),
        "dua_adhan_response" to DuaText("अधान गी जवाब देओ", "अल्लाह दे अलावा कोई ताकत ते कोई ताकत नेईं ऐ।", "मुअज्जिन जेह्ड़ा आखदा ऐ, उʼनें गी दोहाई देओ;'हय्या'अलास-सलाह'ते'हय्या'अलाल-फलाह'च एह् आखेआ जंदा ऐ।", "जेह्ड़ा बी दिलै कन्नै जवाब दिंदा ऐ, ओह् परादीस च दाखल होग।"),
        "dua_adhan_shahadah" to DuaText("मुअज्जिन दी शहादाह दे परैंत्त", "ते में बी गवाही दिंदा आं जे कुसै गी बी पूजा करने दा अधिकार नेईं ऐ छड़ा अकेले अल्लाह गी, बगैर साथी दे, ते मुहम्मद सल्लल्लाह् रसूल उंʼदे सेवक ते रसूल न। में अल्लाह कन्नै प्रभु दे रूपा च, मुहम्मद सल्लल्लाह् रसूल दे रसूल दे रूपा च ते इस्लाम धर्म दे धर्म दे रूपै च प्रसन्न आं।", "मुएज़्ज़िन दी विश्वास दी गवाही सुनने पर।", "उंʼदे पाप माफ कीते जंदे न।"),
        "dua_istiftah_baid" to DuaText("दुआ दा उद्घाटनः मिगी पापें शा दूर करो", "ऐ अल्लाह, मिगी मेरे पापें शा दूर करो की जे तुस पूरब गी पच्छम शा दूर करी ओड़ेआ ऐ। ऐ अल्लाह, मेरे पापें गी ठीक करो जिʼयां इक चिट्टे कपड़े गी मैल कन्नै साफ कीता जंदा ऐ। ऐ अल्लाह, मेरे पापें गी पानी, बर्फ ते ओलै कन्नै धोओ।", "उद्घाटन दे बाद (सना दे थाह्र पर बी आखेआ जाई सकदा ऐ)।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इस दा पाठ तक्बीर ते पाठ दे बिच्च कीता।"),
        "dua_hamdan_kathiran" to DuaText("रुकू दे परैंत्त भरपूर तरीफ", "हे हमारे प्रभु, तुंʼदी स्तुति ऐ-भरपूर, शुद्ध ते बरकतां आह्ली स्तुति।", "रुकू थमां उठी दे बाद,'रब्बाना लकल-हमद'दे कन्नै।", "त्रीएं शा मते स्वर्गदूत इसगी रिकार्ड करने आह्ले पैह्ले व्यक्ति बनने दी दौड़ च हे।"),
        "dua_subbuhun_quddus" to DuaText("सुब्बूहुन कुद्दुस (रुकू ते सुजूद)", "(अल्लाह) सभनें शा महिमावान, सभनें शा पवित्र, स्वर्गदूतां ते आत्मा (जिब्रिल) दा स्वामी ऐ।", "रुकू ते सुजूद च।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने रुकू ते सुजूद च एह् पढ़ा।"),
        "dua_sujood_dhanbi_kullah" to DuaText("सुजूदः मेरे सारे पाप क्षमा करी देओ।", "हे अल्लाह, मेरे सारे पाप-लौह्के ते बड्डे, पैह्ले ते खीरी, खु'ल्ले ते लुके दे-माफ करी देओ।", "सुजूद च।", "प्रोस्ट्रेशन इक नेहा थाह्र ऐ जित्थै दुआएं दा जवाब दित्ता जंदा ऐ।"),
        "dua_sujood_ridaka" to DuaText("अपनी खुशी च शरण लो", "हे अल्लाह, में तुंʼदे क्रोध थमां तेरी खुशी च, तेरी सजा शा तेरी माफी च, पनाह लैंदा आं, ते में तुंʼदे शा पनाह लैंदा आं। में पूरी चाल्ली कन्नै तेरी स्तुति नेईं करी सकदा; तुस उʼनें गै ओ जिʼयां तुस अपनी स्तुति कीती ऐ।", "सुजूद च-आयशा (रा.) ने पैगंबर सल्लल्लाह् अलैहि वसल्लम गी एह् आखदे सुणिआ।", "पैगंबर सल्लल्लाह् अलैहि वसल्लम दा इक सुजूद दुआ।"),
        "dua_tashahhud" to DuaText("ताशाहहुद (अत-तहिय्याह)", "सारे ज़बानी, शारीरिक ते माली पूजा अल्लाह आस्तै ऐ। ऐ पैगंबर, तुंʼदे पर शान्ति होई ते अल्लाह दी दया ते उंʼदी बरकत। हम पर ते अल्लाह दे नेक बंदरें पर शान्ति होई। में गवाही दिंदा आं जे अल्लाह दे अलावा कुसै गी बी पूजा करने दा अधिकार नेईं ऐ, ते में गवाही दिंदा आं जे मुहम्मद सल्लल्लाह् रसूल उंʼदे दास ते रसूल न।", "हर बैठक च-अब्दुल्ला इब्न मसूद (र.) (हनाफी प्रथा) आसेआ सुनाया गेआ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इसगी कुरान दी सूरह दी चाल्ली सिखाया।"),
        "dua_sajdah_tilawah" to DuaText("पाठ दा सजदा", "मेरा मूह् उस गी सिजदा कीता ऐ जिʼन्नै इसगी बनाया ऐ ते अपनी शक्ति ते शक्ति कन्नै इसगी सुनेआ ते दिक्खेआ ऐ।", "पाठ दे नमाज़ च।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने राती दे पाठ च एह् आखेआ।"),
        "dua_after_witr" to DuaText("विटर दे परैंत्त", "परमपवित्र राजा दी महिमा ऐ।", "विदर दी नमाज़ दे परैंत्त त्रै बारी, त्री बारी अवाज बधांदे होई।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् बात विद्र दे परैंत्त आखी।"),
        "dua_tahajjud_nur" to DuaText("तहज्जुद दी शुरुआती विनती", "ऐ अल्लाह, तुंʼदी स्तुति ऐ, तुस आसमानें, धरती ते उंʼदे अंदर दे सारे लोकें दे पालनहार ओ। तुंʼदी स्तुति ऐ, तुस आसमानें, धरती ते उंʼदे अंदर दे सारे लोकें दे चानण ओ। तुंʼदी स्तुति ऐ, तुस सच्च ओ, तुंʼदा वायदा सच्चा ऐ, तुंʼदे कन्नै मुलाकात सच ऐ, तुंʼदा बचन सच्चा ऐ, जन्नत सच ऐ, नरक सच्चा ऐ, पैगंबर सच न, मुहम्मद सल्लल्लाह् अलैहि वसल्लम सच्चा ऐ ते घड़ी सच ऐ।", "जिसलै राती दी नमाज़ (तहज्जुद) (दुआ दा शुरुआती हिस्सा) शुरू होंदा ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने तहज्जुद आस्तै उठीने पर एह् पढ़ा (पूरा दुआ अल-बुखारी च ऐ)।"),
        "dua_rabba_jibrail" to DuaText("विवादत मामलें च मेरा मार्गदर्शन करो", "ऐ अल्लाह, जिब्रिल, मीकाईल ते इसराफिल दे रब, आकाशें ते धरती दे रचयिता, नग्गे ते नजारे दे जानकार! तुस अपने दासें दे बिच्च उस गल्ल दा फैसला करोगे जेह्दे च ओह् मतभेद करदे हे। अपनी इजाज़त कन्नै मिगी सच्चाई दी बक्खी नयुक्त करो जेह्दे पर मतभेद होए दा ऐ। निश्चय गै तुस जिस्सी मनदे ओ उसी सीधे रस्ते पर नयुक्त करदे ओ।", "तहज्जुद दी शुरुआत च-असहमति दे बिच्च सचै दे मार्गदर्शन आस्तै।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इस दुआ कन्नै अपनी रात दी नमाज़ दी शुरुआत कीती।"),
        "dua_going_to_mosque_nur" to DuaText("मस्जिद (रोशनी दा दुआ) जाना", "हे अल्लाह, मेरे दिल च रौशनी लाओ, मेरीएंएं च रौशनी, मेरे कानें च रौशनी, मेरे सज्जे च रौशनी, मेरे खब्बे च रौशनी, मेरे उप्पर रौशनी, मेरे खʼल्ल रौशनी, मेरे अग्गें रौशनी, मेरे पिछांह् च रौशनी लाओ ते मेरे आस्तै रौशनी बनाओ।", "फजर आस्तै मस्जिद जंदे होई।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने नमाज़ पढ़ने आस्तै बाह्र जाने दे दुरान एह् पढ़ा।"),
        "dua_waswasa_salah" to DuaText("सलाह दे दुरान वासवासा (खिंजाब)", "में शापित शयतान शा अल्लाह दी शरण मंगदा आं।", "जिसलै प्रार्थना दे दुरान शैतान दियां फुसफुसियां आउदियां न, तां शरण लओ ते त्रै बारी खब्बी बक्खी हलके-फुल्के थूक।", "उथमान इब्न अबिल -'अस (र.) ने एह् कीता ते फुसफुसियां चली गेइयां।"),
        "dua_alimal_ghayb" to DuaText("अनदेखे दा पता होना", "ऐ अल्लाह, जो अदृश्य ते दर्शनी चीजें गी जाने दा ऐ, आकाशें ते धरती दा निर्माता ऐ, हर चीज दा रब ऐ ते शासक ऐ! में गवाही दिंदा आं जे तेरे बगैर कोई पूज्य-प्रभु नेईं ऐ। में अपने आप दी बुराई, शयतान ते ओह्दे शरक दी बुराई शा तुंʼदे च शरण लैंदा आं।", "भ्यागा, सʼज ते सोने शा पैह्लें-पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अबू बकर (र.) गी एह् सिखाया।", "अपने आप ते शैतान दी बुराई शा सुरक्षा।"),
        "dua_fitratil_islam" to DuaText("इस्लाम दे फित्राह पर", "इस्लाम दे फित्रै पर, इमानदारी दे शब्द पर, अपने पैगंबर मुहम्मद सल्लल्लाह् अलैहि वसल्लम दे धर्म पर ते अपने पिता इब्राहिम (ए. ऐस्स.) दे रस्ते पर, जेह्ड़े सच्च ते मुसलमान हे, ते मुशरिकें दे नेईं हे, असीं भ्यागा दाखल होए न।", "भ्यागा।", "हर भ्यागा अपने विश्वास गी परतियै स्थापत करो।"),
        "dua_amsayna_fitrah" to DuaText("इस्लाम दे फित्राह पर सʼञै", "असां इस्लाम दी फित्रै पर, इमानदारी दे शब्द पर, अपने पैगंबर मुहम्मद सल्लल्लाह् अलैहि वसल्लम दे धर्म पर ते अपने पिता इब्राहिम (ए. ऐस्स.) दे रस्ते पर सʼञै दाखल होए आं, जेह्ड़े सच्च ते मुसलमान हे, ते मुशरिकें चा नेईं हे।", "सʼञै दा।", "हर सʼञै अपने विश्वास गी परतियै स्थापत करो।"),
        "dua_tahleel_10_fajr" to DuaText("फजर ते मगरिब दे परैंत्त दस तहलील", "कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अल्लाह गी, बगैर साथी दे। प्रभुत्व ते स्तुति उसी दी ऐ। ओह् जीवन दिंदा ऐ ते मौत करदा ऐ, ते ओह् हर चीज पर अधिकार रखदा ऐ।", "अपने बैठने जां बोलने शा हटने शा पैह्लें, फजर (ते माघरीब) दे दस बारी परैंत्त।", "दस भले कर्म, दस पाप मिटाई गे, दस रैंकें गी उभारिआ गेआ ते सारा दिन शैतान शा सुरक्षा।"),
        "dua_la_hawla_kanz" to DuaText("जन्ना दा खजाना", "अल्लाह दे अलावा कोई ताकत ते कोई ताकत नेईं ऐ।", "अक्सर, हर समें।", "एह् परादीस दे खजानें बिच्चा इक ऐ।"),
        "dua_four_beloved_words" to DuaText("चार सभनें शा प्यार करने आह्ले शब्द", "महिमावान ऐ अल्लाह, सारी स्तुति अल्लाह आस्तै ऐ, अल्लाह दे अलावा कुसै गी बी पूजा करने दा अधिकार नेईं ऐ, ते अल्लाह सभनें शा महान ऐ।", "ओह् शब्द जेह्ड़े अल्लाह गी सभनें शा मते प्यार करदे न।", "ओह् पैगंबर सल्लल्लाहु अलैहि वसल्लम गी सूरज दे उगम दी हर चीज कोला मते प्यारे न।"),
        "dua_two_light_words" to DuaText("दो शब्द जीभ पर चानण", "महिमावान अल्लाह ऐ ते सारी तरीफ उसी ऐ; महिमावान अल्लाह ऐ।", "जीभ पर हलका, स्केल पर भारी।", "परम दयावान गी प्यार करदे होई, जीभ पर चानण ते स्केल पर भारी। (अल-बुखारी दी खीरली हदीस)"),
        "dua_ya_dhal_jalal" to DuaText("या धल-जलाली वाल-इकराम", "हे महामहिम ते सम्मान दे स्वामी!", "पैगंबर दे निर्देश-दुआ च इसगी फड़ी र'व।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआः'या-जलाली वाल-इकराम'गी फड़ी र'व।"),
        "dua_sleep_wadatu_janbi" to DuaText("तेरे नांऽ पर में सु'यां", "हे मेरे प्रभु, में तेरे नांऽ पर अपना पक्ष रखदा आं ते तेरे नांऽ पर जागदा आं। जे तुस मेरी जान लैंदे ओ, तां उस पर दया करो, ते जे तुस इसगी मुक्त करदे ओ, तां उसी बचाओ जिʼयां तुस अपने धर्मी सेवकें दी रक्षा करदे ओ।", "बिस्तर गी धूली कन्नै धोने दे परैंत्त ते लेटने दे परैंत्त।", "सोने शा पैह्लें अपनी आत्मा अल्लाह गी सुपुर्द करो।"),
        "dua_sleep_khalaqta_nafsi" to DuaText("तुस मेरी आत्मा बनाई ऐ", "ऐ अल्लाह, तुस मेरी जान बनाई ऐ ते तुस इसगी लेई लवोगे। उंʼदी मौत ते उंʼदी जान तुंʼदी ऐ। जे तुस इसगी जिंदा रखदे ओ, तां उंʼदी रक्षा करो, ते जे तुस इसगी मरने दिंदे ओ, तां इसगी माफ करी देओ। ऐ अल्लाह, में तुंʼदी भलाई आस्तै विनती करदा आं।", "सोंदे शा पैह्लें-इब्न उमर (र.) आसेआ सुनाया गेआ ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने सोंदे समें एह् आखने दा निर्देश दित्ता।"),
        "dua_sleep_atamana" to DuaText("सौने शा पैह्लें आभार प्रकट करो", "सारी स्तुति अल्लाह आस्तै ऐ जिʼन्नै असां गी पोशी दित्ता, सानू पींदा दित्ता, सानू काफी कीता ते सानू शरण दित्ती। किन्ने लोक न जिंʼदे कोल नेहा कोई ऐ जेह्ड़ा उंʼदे आस्तै काफी नेईं ऐ ते नेईं गै उʼनें गी पनाह देई सकदा ऐ।", "जिसलै सोंदे ओ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने सोंदे समें एह् आखेआ हा।"),
        "dua_sleep_rabbas_samawat" to DuaText("स्वर्ग दे स्वामी-साडा कर्ज चुकाओ", "ऐ अल्लाह, आसमानें, धरती ते पराक्रमी संघासन दे रब, साडा रब ते हर चीज दे रब, बीज ते खर्जूर दे टुकड़े करने आह्ले, तोराह, इंजिल ते फुरकान दे प्रगट करने आह्ले! में हर उस बुराई थमां तेरी शरण लैंदा आं जिस्सी तुस पकड़दे ओ। ऐ अल्लाह, तुस पैह्लें ओ, तुंʼदे पैह्लें किश बी नेईं ऐ। तुस खीरी ओ, तुंʼदे परैंत्त किश बी नेईं ऐ; तुस गै प्रगट न, अपने कोला मता किश बी नेईं ऐ, तुस छिपी होई ओ, अपने शा किश बी नेईं छुपा ऐ। साडे आस्तै साडा कर्ज चुकाई देओ ते सानू गरीबी शा मुक्त करो।", "सोंदे शा पैह्लें, सज्जे पासे पर लेटना-फातिमा (रा.) गी सिखाया।", "कर्ज ते कठिनाई थमां राहत आस्तै इक दुआ।"),
        "dua_sleep_fear" to DuaText("नींद च डर जां बेचैनी", "में अल्लाह दे गुस्स ते उंʼदी सज़ाया, उंʼदे सेवकें दी बुराई, शैतानें दी फुसफुस ते उंʼदे मेरे कोल औने शा उंʼदे परिपूर्ण वचनें च शरण मंगदा आं।", "जिसलै नींद च डर जां बेचैनी महिसूस करदे ओ।", "नेहा करने कन्नै, उस चीज कन्नै उʼनें गी कोई नुकसान नेईं होग।"),
        "dua_waking_afani" to DuaText("जागनाः उʼनें मेरी आत्मा गी परतियै स्थापत कीता", "सारी स्तुति अल्लाह आस्तै ऐ जिʼन्नै मेरे शरीर गी चंगा कीता, मेरी आत्मा गी मिगी बापस करी दित्ता ते मिगी उʼनें गी चेता करने दी इजाज़त दित्ती।", "जागने पर।", "इक नमीं भ्यागा आस्तै आभार।"),
        "dua_allahu_rabbi" to DuaText("अल्लाह, अल्लाह मेरा रब ऐ।", "ऐ अल्लाह, अल्लाह मेरा रब ऐ; में ओह्दे कन्नै किश बी शरिक नेईं करदा।", "दुख जां दुख च-पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अस्मा बिन्त उमैस (रा.) गी एह् सिखाया।", "मुसीबत दे समें तौहीद गी फड़ी रक्खेआ।"),
    )
}
